public class DateTimeZone_adjustOffset_TriageGen1Test {

    private static final long MILLIS_PER_HOUR = 3600000L;

    /**
     * Test Case 1: Non-overlap scenario (Gap or Normal case)
     * Where instantBefore == instantAfter.
     * This covers the first 'if' branch.
     */
    @Test
    public void testAdjustOffset_NoOverlap() {
        // We use a spy to control the behavior of convertUTCToLocal
        // to simulate the condition (instantBefore == instantAfter)
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(0));
        long instant = 1000L;

        // Mocking: instantBefore = convert(instant - 3h), instantAfter = convert(instant + 3h)
        // To make instantBefore == instantAfter, we make the conversion return a constant
        when(zone.convertUTCToLocal(instant - 3 * MILLIS_PER_HOUR)).thenReturn(5000L);
        when(zone.convertUTCToLocal(instant + 3 * MILLIS_PER_HOUR)).thenReturn(5000L);

        long result = zone.adjustOffset(instant, true);

        assertEquals(instant, result);
    }

    /**
     * Test Case 2: Overlap scenario - earlierOrLater is true
     * This covers the second branch: convertLocalToUTC(local, false, instantAfter)
     */
    @Test
    public void testAdjustOffset_Overlap_EarlierOrLaterTrue() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(0));
        long instant = 1000L;
        long local = 2000L;
        long instantAfter = 3000L;
        long expectedResult = 4000L;

        // Simulate overlap: instantBefore != instantAfter
        when(zone.convertUTCToLocal(instant - 3 * MILLIS_PER_HOUR)).thenReturn(100L);
        when(zone.convertUTCToLocal(instant + 3 * MILLIS_PER_HOUR)).thenReturn(500L);

        // Mock the local calculation
        when(zone.convertUTCToLocal(instant)).thenReturn(local);

        // Mock the return value for the specific overload: 
        // convertLocalToUTC(long instantLocal, boolean strict, long originalInstantUTC)
        when(zone.convertLocalToUTC(eq(local), eq(false), eq(instantAfter))).thenReturn(expectedResult);

        long result = zone.adjustOffset(instant, true);

        assertEquals(expectedResult, result);
    }

    /**
     * Test Case 3: Overlap scenario - earlierOrLater is false
     * This covers the second branch: convertLocalToUTC(local, false, instantBefore)
     */
    @Test
    public void testAdjustOffset_Overlap_EarlierOrLaterFalse() {
        DateTimeZone zone = spy(DateTimeZone.forOffsetHours(0));
        long instant = 1000L;
        long local = 2000L;
        long instantBefore = 3000L;
        long expectedResult = 4000L;

        // Simulate overlap: instantBefore != instantAfter
        when(zone.convertUTCToLocal(instant - 3 * MILLIS_PER_HOUR)).thenReturn(100L);
        when(zone.convertUTCToLocal(instant + 3 * MILLIS_PER_HOUR)).thenReturn(500L);

        // Mock the local calculation
        when(zone.convertUTCToLocal(instant)).thenReturn(local);

        // Mock the return value for the specific overload: 
        // convertLocalToUTC(long instantLocal, boolean strict, long originalInstantUTC)
        when(zone.convertLocalToUTC(eq(local), eq(false), eq(instantBefore))).thenReturn(expectedResult);

        long result = zone.adjustOffset(instant, false);

        assertEquals(expectedResult, result);
    }
}
